typedef struct { FILE *f; char buf[4096]; int done; } LineIter;

bool line_iter_next(LineIter *it, const char **out) {
    if (it->done || !fgets(it->buf, sizeof it->buf, it->f)) { it->done = 1; return false; }
    *out = it->buf;                 /* one element per call */
    return true;
}

LineIter it = { .f = fopen("huge.log", "r") };
const char *line;
while (line_iter_next(&it, &line)) { if (strstr(line, "ERROR")) break; }  /* early stop */
fclose(it.f);

