static ucontext_t gen_ctx, caller_ctx;   /* one small stack per generator */

static void producer(void) {
    for (;;) { swapcontext(&gen_ctx, &caller_ctx); }   /* resume point */
}

void pull_first(void) { getcontext(&gen_ctx); producer(); }  /* simplified */
